settings.custom_liquid:
{%- comment -%}
  Fitting Guide Popup
  --------------------
  এই কোডটি প্রোডাক্ট পেইজের যেকোনো জায়গায় Custom Liquid ব্লকে বসিয়ে দিলেই কাজ করবে।
  "Fitting Guide" বাটনে ক্লিক করলে পপআপ ওপেন হবে, ওভারলে বা ✕ বাটনে ক্লিক করলে ক্লোজ হবে।
{%- endcomment -%}

<button type="button" class="fg-trigger" id="fgTrigger">Fitting Guide</button>

<div class="fg-popup" id="fgPopup" aria-hidden="true">
  <div class="fg-overlay" id="fgOverlay"></div>

  <div class="fg-content" role="dialog" aria-modal="true" aria-labelledby="fgTitle">
    <button type="button" class="fg-close" id="fgClose" aria-label="Close">&times;</button>

    <h4 id="fgTitle" class="fg-title">Fitting Guide</h4>

    <div class="fg-body">
      <p>All the lasts and models launched by ACME Shoemaker are self-developed, each has been repeatedly debugged hundreds of times and continuously improved according to the experiences of different wearers, striving to achieve high adaptability for each model and last.</p>
      <p>We manufacture shoes in UK sizes. Since human foot size is very complicated, we highly recommend that you contact us and share your daily shoe wearing experiences, then based on the size chart we provide below we can discuss together to choose the right ACME Shoemaker shoe size for you.</p>
      <p>Check our size guide for a size conversion to UK / US / EU sizing on footwear.</p>

      <h3>Width Guide</h3>
      <table class="fg-table">
        <thead>
          <tr>
            <th>&nbsp;</th>
            <th>UK</th>
            <th>US</th>
            <th>ACME</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>Narrow</td>
            <td>E</td>
            <td>C</td>
            <td>E</td>
          </tr>
          <tr>
            <td>Standard</td>
            <td>F</td>
            <td>D</td>
            <td>F</td>
          </tr>
          <tr>
            <td>Wide</td>
            <td>G</td>
            <td>E</td>
            <td>G</td>
          </tr>
        </tbody>
      </table>

      <p>The width standard of ACME Shoemaker shoes is based on the UK shoe size (Sioux), which is optimized according to our lasts and the accumulation of data on customer's foot shape, the standard width of ACME Shoemaker shoe is F.</p>

      <h3>Size Guide</h3>
      <table class="fg-table">
        <thead>
          <tr>
            <th>ACME</th>
            <th>UK</th>
            <th>US</th>
            <th>EU</th>
          </tr>
        </thead>
        <tbody>
          <tr><td>5</td><td>5</td><td>6</td><td>39</td></tr>
          <tr><td>5.5</td><td>5.5</td><td>6.5</td><td>39.5</td></tr>
          <tr><td>6</td><td>6</td><td>7</td><td>40</td></tr>
          <tr><td>6.5</td><td>6.5</td><td>7.5</td><td>40.5</td></tr>
          <tr><td>7</td><td>7</td><td>8</td><td>41</td></tr>
          <tr><td>7.5</td><td>7.5</td><td>8.5</td><td>41.5</td></tr>
          <tr><td>8</td><td>8</td><td>9</td><td>42</td></tr>
          <tr><td>8.5</td><td>8.5</td><td>9.5</td><td>42.5</td></tr>
          <tr><td>9</td><td>9</td><td>10</td><td>43</td></tr>
          <tr><td>9.5</td><td>9.5</td><td>10.5</td><td>43.5</td></tr>
          <tr><td>10</td><td>10</td><td>11</td><td>44</td></tr>
          <tr><td>10.5</td><td>10.5</td><td>11.5</td><td>44.5</td></tr>
          <tr><td>11</td><td>11</td><td>12</td><td>45</td></tr>
          <tr><td>11.5</td><td>11.5</td><td>12.5</td><td>45.5</td></tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

<style>
  .fg-trigger {
    background: #111;
    color: #fff;
    border: 1px solid #111;
    padding: 12px 22px;
    font-size: 13px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    cursor: pointer;
    transition: background 0.2s ease, color 0.2s ease;
  }
  .fg-trigger:hover {
    background: #fff;
    color: #111;
  }

  .fg-popup {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    margin: 0 !important;
    z-index: 999999;
    display: none;
  }
  .fg-popup.is-open {
    display: block;
  }

  .fg-overlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
  }

  .fg-content {
    position: relative;
    width: 100%;
    max-width: 820px;
    height: 100vh;
    margin: 0 auto !important;
    background: #fff;
    color: #333;
    padding: 60px 50px 80px;
    overflow-y: auto;
    box-shadow: 0 0 40px rgba(0, 0, 0, 0.15);
    box-sizing: border-box;
  }

  .fg-close {
    position: absolute;
    top: 22px;
    right: 24px;
    background: transparent;
    border: none;
    font-size: 24px;
    line-height: 1;
    cursor: pointer;
    color: #333;
  }
  .fg-close:hover {
    color: #111;
  }

  .fg-title {
    max-width: 760px;
    margin: 0 auto 36px;
    font-size: 26px;
    font-weight: 400;
    text-align: center;
    text-transform: none;
    letter-spacing: 0.01em;
    border-bottom: none;
    padding-bottom: 0;
    color: #000;
  }

  .fg-body {
    max-width: 760px;
    margin: 0 auto;
  }

  .fg-body p {
    font-size: 15px;
    line-height: 1.7;
    margin: 0 0 20px;
    color: #555;
  }

  .fg-body h3 {
    font-size: 22px;
    font-weight: 400;
    text-transform: none;
    letter-spacing: normal;
    margin: 36px 0 20px;
    color: #222;
  }

  .fg-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
    font-size: 14px;
  }
  .fg-table th,
  .fg-table td {
    border: 1px solid #e0e0e0;
    padding: 14px 12px;
    text-align: center;
  }
  .fg-table thead th {
    background: #111;
    color: #fff;
    text-transform: none;
    font-size: 14px;
    font-weight: 400;
    letter-spacing: normal;
    border-color: #111;
  }
  .fg-table tbody tr {
    background: #fff;
  }

  @media (max-width: 480px) {
    .fg-content {
      max-width: 100%;
      padding: 50px 18px 60px;
    }
    .fg-close {
      top: 16px;
      right: 16px;
    }
    .fg-title {
      font-size: 20px;
    }
    .fg-body h3 {
      font-size: 18px;
    }
    .fg-table th,
    .fg-table td {
      padding: 8px 6px;
      font-size: 12px;
    }
  }
</style>

<script>
  (function () {
    var trigger = document.getElementById('fgTrigger');
    var popup = document.getElementById('fgPopup');
    var overlay = document.getElementById('fgOverlay');
    var closeBtn = document.getElementById('fgClose');

    /* Shopify থিমে অনেক সময় parent element-এ transform/perspective থাকে,
       যেটার কারণে position:fixed viewport এর বদলে ওই parent-এর সাপেক্ষে বসে যায়
       (ফলে পপআপ ডান পাশে/ভুল জায়গায় দেখা যায়)।
       এটা এড়াতে popup-কে সরাসরি <body>-এর child বানিয়ে দিচ্ছি। */
    document.body.appendChild(popup);

    function openPopup() {
      popup.classList.add('is-open');
      popup.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }

    function closePopup() {
      popup.classList.remove('is-open');
      popup.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
    }

    trigger.addEventListener('click', openPopup);
    overlay.addEventListener('click', closePopup);
    closeBtn.addEventListener('click', closePopup);

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && popup.classList.contains('is-open')) {
        closePopup();
      }
    });
  })();
</script>
